import{_ as e,o as a,c as i,a4 as n}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"认证","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/07-security/chapter-02-authentication.md","filePath":"engineering/07-security/chapter-02-authentication.md"}'),r={name:"engineering/07-security/chapter-02-authentication.md"};function c(s,t,l,d,o,h){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="认证" tabindex="-1" data-src-line="1" data-src-file="engineering/07-security/chapter-02-authentication.md">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="3" data-src-file="engineering/07-security/chapter-02-authentication.md"><strong>核心问题</strong>：Session vs JWT 如何选择？OAuth2 的流程是什么？如何实现安全的认证？</p></blockquote><h2 id="_1-session-认证" tabindex="-1" data-src-line="5" data-src-file="engineering/07-security/chapter-02-authentication.md">1. Session 认证 <a class="header-anchor" href="#_1-session-认证" aria-label="Permalink to &quot;1. Session 认证&quot;">​</a></h2><p data-src-line="7" data-src-file="engineering/07-security/chapter-02-authentication.md">Session 认证的流程：</p><ol data-src-line="9" data-src-file="engineering/07-security/chapter-02-authentication.md"><li data-src-line="9" data-src-file="engineering/07-security/chapter-02-authentication.md">用户登录，服务端创建 Session，返回 SessionID（通常放在 Cookie 里）</li><li data-src-line="10" data-src-file="engineering/07-security/chapter-02-authentication.md">后续请求携带 Cookie，服务端据此找到对应 Session</li></ol><p data-src-line="12" data-src-file="engineering/07-security/chapter-02-authentication.md">Session 方案的关键配置点：登录处理、权限校验（放行公开接口、拦截需认证接口）、会话管理（单点登录、会话过期）。</p><blockquote data-src-line="14" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="14" data-src-file="engineering/07-security/chapter-02-authentication.md">各框架的 Session 落地代码见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><h2 id="_2-jwt-认证" tabindex="-1" data-src-line="16" data-src-file="engineering/07-security/chapter-02-authentication.md">2. JWT 认证 <a class="header-anchor" href="#_2-jwt-认证" aria-label="Permalink to &quot;2. JWT 认证&quot;">​</a></h2><p data-src-line="18" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 由三部分组成：<code>Header.Payload.Signature</code>，用 <code>.</code> 分隔。服务端签发时用密钥对 Header + Payload 签名，客户端无状态携带，服务端校验签名即可确认身份，无需存储会话。</p><p data-src-line="20" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 校验的关键点：验证签名、验证过期时间、验证签发方。校验通过后将用户身份写入当前请求上下文。</p><blockquote data-src-line="22" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="22" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 的签发与过滤器落地代码见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><h2 id="_3-session-vs-jwt-对比" tabindex="-1" data-src-line="24" data-src-file="engineering/07-security/chapter-02-authentication.md">3. Session vs JWT 对比 <a class="header-anchor" href="#_3-session-vs-jwt-对比" aria-label="Permalink to &quot;3. Session vs JWT 对比&quot;">​</a></h2><table tabindex="0"><thead data-src-line="26" data-src-file="engineering/07-security/chapter-02-authentication.md"><tr data-src-line="26" data-src-file="engineering/07-security/chapter-02-authentication.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Session</th><th style="text-align:left;">JWT</th></tr></thead><tbody data-src-line="28" data-src-file="engineering/07-security/chapter-02-authentication.md"><tr data-src-line="28" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">存储位置</td><td style="text-align:left;">服务端</td><td style="text-align:left;">客户端</td></tr><tr data-src-line="29" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">扩展性</td><td style="text-align:left;">需要共享 Session 存储</td><td style="text-align:left;">无状态，天然支持分布式</td></tr><tr data-src-line="30" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">安全性</td><td style="text-align:left;">服务端可控</td><td style="text-align:left;">Token 泄露风险</td></tr><tr data-src-line="31" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">撤销</td><td style="text-align:left;">难以撤销</td><td style="text-align:left;">难以撤销（需黑名单）</td></tr><tr data-src-line="32" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">传统 Web 应用</td><td style="text-align:left;">API、移动端、微服务</td></tr></tbody></table><h2 id="_4-oauth2-流程" tabindex="-1" data-src-line="34" data-src-file="engineering/07-security/chapter-02-authentication.md">4. OAuth2 流程 <a class="header-anchor" href="#_4-oauth2-流程" aria-label="Permalink to &quot;4. OAuth2 流程&quot;">​</a></h2><p data-src-line="36" data-src-file="engineering/07-security/chapter-02-authentication.md">OAuth2 授权码模式：</p><ol data-src-line="38" data-src-file="engineering/07-security/chapter-02-authentication.md"><li data-src-line="38" data-src-file="engineering/07-security/chapter-02-authentication.md">用户点击「微信登录」，跳转到微信授权页面</li><li data-src-line="39" data-src-file="engineering/07-security/chapter-02-authentication.md">用户授权后，微信回调你的应用，带上 <code>authorization_code</code></li><li data-src-line="40" data-src-file="engineering/07-security/chapter-02-authentication.md">你的应用用 <code>code</code> 换取 <code>access_token</code></li><li data-src-line="41" data-src-file="engineering/07-security/chapter-02-authentication.md">用 <code>access_token</code> 获取用户信息</li></ol><blockquote data-src-line="43" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="43" data-src-file="engineering/07-security/chapter-02-authentication.md">OAuth2 各提供方的接入配置见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><blockquote data-src-line="45" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="45" data-src-file="engineering/07-security/chapter-02-authentication.md"><strong>认证的核心</strong>：验证&quot;你是谁&quot;。Session 适合传统 Web，JWT 适合 API 和微服务，OAuth2 适合第三方登录。选择哪种方式取决于你的应用场景。</p></blockquote>',18)])])}const p=e(r,[["render",c]]);export{g as __pageData,p as default};
